export const ACTIONS=[['KeyW','Accelerate'],['KeyS','Brake'],['KeyA','Steer left'],['KeyD','Steer right'],['Space','Handbrake'],['KeyF','Fire'],['KeyX','Next weapon'],['KeyT','Cycle target'],['KeyC','Camera'],['KeyJ','Autopilot'],['KeyH','HUD'],['KeyP','Pause'],['KeyQ','Recover'],['KeyE','Enter pit'],['KeyR','Restart / retire'],...Array.from({length:7},(_,i)=>['Digit'+(i+1),'Weapon '+(i+1)])];
const reserved=['Escape','Tab','Enter','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];
export const keyLabel=code=>code==='Space'?'Space':code.replace(/^Key|^Digit/,'');
export function padInput(p,deadzone=.18){const button=i=>Math.max(0,Math.min(1,Number(p?.buttons[i]?.value)||0)),x=Number(p?.axes[0])||0;return {steer:Math.abs(x)<=deadzone?0:Math.sign(x)*Math.min(1,(Math.abs(x)-deadzone)/(1-deadzone)),throttle:button(7)>.05?button(7):0,brake:button(6)>.05?button(6):0,fire:button(0)>.5,handbrake:button(1)>.5};}
export function createControls(onChange){
 const key='deathtrack.remaster.controls.v1';let bindings=Object.fromEntries(ACTIONS.map(([k])=>[k,k])),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,enabled=true,deadzone=.18,capture=null,previous=[],padIndex=null,armed=false,choice='auto';
 try{const s=JSON.parse(localStorage.getItem(key));if(s){if(s.bindings&&ACTIONS.every(([k])=>typeof s.bindings[k]==='string'&&/^(Key[A-Z]|Digit[0-9]|Space|Numpad[0-9]|Backquote|Minus|Equal|BracketLeft|BracketRight|Backslash|Semicolon|Quote|Comma|Period|Slash)$/.test(s.bindings[k]))&&new Set(Object.values(s.bindings)).size===ACTIONS.length)bindings=s.bindings;if(typeof s.reduced==='boolean')reduced=s.reduced;if(typeof s.enabled==='boolean')enabled=s.enabled;if(s.deadzone>=.1&&s.deadzone<=.4)deadzone=s.deadzone;}}catch{}
 const box=document.createElement('fieldset');box.className='hud-options';box.innerHTML='<legend>Controls & comfort</legend><label class="check"><input id="reduced-shake" type="checkbox"> Reduced camera shake & speed zoom</label><label class="check"><input id="enable-gamepad" type="checkbox"> Enable gamepad</label><label>Controller<select id="pad-choice"><option value="auto">First standard controller</option></select></label><label>Stick deadzone<input id="pad-deadzone" type="range" min="10" max="40"></label><p id="pad-status" role="status"></p><p>Left stick: steer · RT/R2: accelerate · LT/L2: brake · A/Cross: fire · B/Circle: handbrake · X/Square: next weapon · Y/Triangle: target · LB/L1: camera · RB/R1: autopilot · View/Select: HUD · Start/Options: pause · Left stick click: recover · Right stick click: pit. Release controls after connecting or closing a dialog.</p><details><summary>Rebind keyboard</summary><p>Choose an action, then press a key. Escape cancels. Arrow driving keys and Escape pause remain available. Duplicate bindings are rejected.</p><div id="key-bindings"></div><button id="reset-bindings" type="button">Reset keyboard defaults</button><p id="binding-status" role="status"></p></details>';
 document.querySelector('#settings-dialog h2').after(box);const $=s=>box.querySelector(s);
 function padStatus(value){if($('#pad-status').textContent!==value)$('#pad-status').textContent=value;}
 function save(){try{localStorage.setItem(key,JSON.stringify({bindings,reduced,enabled,deadzone}));}catch{$('#binding-status').textContent='Preferences apply for this session; storage is unavailable.';}onChange?.();}
 function render(){const grid=$('#key-bindings');grid.replaceChildren();for(const [id,label] of ACTIONS){const b=document.createElement('button');b.type='button';b.textContent=label+' · '+keyLabel(bindings[id]);b.onclick=()=>{capture=id;$('#binding-status').textContent='Press a key for '+label+' (Escape cancels).';};grid.append(b);}}
 $('#reduced-shake').checked=reduced;$('#enable-gamepad').checked=enabled;$('#pad-deadzone').value=deadzone*100;
 $('#reduced-shake').onchange=e=>{reduced=e.target.checked;save();};$('#enable-gamepad').onchange=e=>{enabled=e.target.checked;armed=false;save();};$('#pad-deadzone').oninput=e=>{deadzone=Number(e.target.value)/100;armed=false;save();};$('#pad-choice').onchange=e=>{choice=e.target.value;armed=false;padIndex=null;};$('#reset-bindings').onclick=()=>{bindings=Object.fromEntries(ACTIONS.map(([k])=>[k,k]));capture=null;render();save();$('#binding-status').textContent='Default keyboard restored.';};
 addEventListener('keydown',e=>{if(!capture)return;e.preventDefault();e.stopImmediatePropagation();if(e.code==='Escape'){capture=null;$('#binding-status').textContent='Rebinding cancelled.';return;}if(e.repeat)return;if(e.ctrlKey||e.metaKey||e.altKey||reserved.includes(e.code)||!/^(Key[A-Z]|Digit[0-9]|Space|Numpad[0-9]|Backquote|Minus|Equal|BracketLeft|BracketRight|Backslash|Semicolon|Quote|Comma|Period|Slash)$/.test(e.code)){$('#binding-status').textContent='Use a letter, number, punctuation key or Space.';return;}if(Object.entries(bindings).some(([k,v])=>k!==capture&&v===e.code)){$('#binding-status').textContent='That key is already assigned. Choose another key.';return;}bindings[capture]=e.code;capture=null;render();save();$('#binding-status').textContent='Binding saved.';},true);
 document.querySelector('#settings-dialog').addEventListener('close',()=>{capture=null;armed=false;});render();
 return {get reduced(){return reduced;},label:k=>keyLabel(bindings[k]||k),translate:code=>['Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(code)?code:Object.keys(bindings).find(k=>bindings[k]===code)||null,reset(){armed=false;previous=[];},poll(blocked){let pads=[];try{pads=Array.from(navigator.getGamepads?.()||[]).filter(p=>p?.connected);}catch{}const supported=pads.filter(p=>p.mapping==='standard');const options=JSON.stringify(supported.map(p=>[p.index,p.id]));if($('#pad-choice').dataset.list!==options){$('#pad-choice').dataset.list=options;$('#pad-choice').replaceChildren(new Option('First standard controller','auto'),...supported.map(p=>new Option(p.id,String(p.index))));$('#pad-choice').value=choice;}
 const p=enabled?(choice==='auto'?supported[0]:supported.find(p=>String(p.index)===choice)):null;const disconnected=padIndex!==null&&(!p||p.index!==padIndex);if(!p){padIndex=null;armed=false;previous=[];padStatus(!enabled?'Gamepad disabled':pads.length?'Controller mapping unsupported; use keyboard or a standard controller.':'No controller detected. Connect one and press a button.');return {input:{},actions:[],disconnected};}
 if(p.index!==padIndex){padIndex=p.index;armed=false;previous=[];}const input=padInput(p,deadzone),buttons=p.buttons.map(b=>b.pressed||b.value>.5);if(blocked){armed=false;previous=buttons;}else if(!armed){if(!input.steer&&!input.throttle&&!input.brake&&!buttons.some(Boolean))armed=true;previous=buttons;}
 const actions=[];if(armed&&!blocked)for(const [i,code] of [[2,'KeyX'],[3,'KeyT'],[4,'KeyC'],[5,'KeyJ'],[8,'KeyH'],[9,'KeyP'],[10,'KeyQ'],[11,'KeyE']])if(buttons[i]&&!previous[i])actions.push(code);previous=buttons;padStatus(p.id+(armed?' · Ready':' · Release sticks and buttons to arm'));return {input:armed&&!blocked?input:{},actions,disconnected};}};
}
